import { useState, useEffect } from 'react';
import axios from 'axios';
import '../styles/RequestForm.css';

const RequestForm = ({ onCreated }) => {
  const [type, setType] = useState('event');
  const [responsibleId, setResponsibleId] = useState('');
  const [rooms, setRooms] = useState([]);
  const [employees, setEmployees] = useState([]);
  const [errors, setErrors] = useState({});
  const [formData, setFormData] = useState({
    date: '', startTime: '', endTime: '', room: '',
    needVideo: false, needSound: false, needProjector: false, extraInfo: '',
    repairRoom: '', description: '',
    location: '', videoStartTime: '', videoEndTime: '', usageInfo: ''
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [roomsRes, employeesRes] = await Promise.all([axios.get('/api/rooms'), axios.get('/api/admin/employees')]);
        setRooms(roomsRes.data);
        setEmployees(employeesRes.data);
      } catch (err) { console.error(err); }
    };
    fetchData();
  }, []);

  const handleChange = (e) => {
    const { name, value, type: inputType, checked } = e.target;
    setFormData(prev => ({ ...prev, [name]: inputType === 'checkbox' ? checked : value }));
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: undefined }));
  };

  const validate = () => {
    const newErrors = {};
    if (type === 'event') {
      if (!formData.date) newErrors.date = 'Дата обязательна';
      if (!formData.startTime) newErrors.startTime = 'Время начала обязательно';
      if (!formData.endTime) newErrors.endTime = 'Время окончания обязательно';
      if (!formData.room) newErrors.room = 'Выберите аудиторию';
      if (formData.startTime && formData.endTime && formData.startTime >= formData.endTime) newErrors.endTime = 'Окончание позже начала';
      if (formData.date && formData.startTime && new Date(`${formData.date}T${formData.startTime}`) < new Date()) newErrors.startTime = 'Нельзя в прошлом';
    } else if (type === 'repair') {
      if (!formData.repairRoom) newErrors.repairRoom = 'Аудитория обязательна';
      if (!formData.description.trim()) newErrors.description = 'Опишите проблему';
    } else {
      if (!formData.location) newErrors.location = 'Место обязательно';
      if (!formData.videoStartTime) newErrors.videoStartTime = 'Время начала обязательно';
      if (!formData.videoEndTime) newErrors.videoEndTime = 'Время окончания обязательно';
      if (formData.videoStartTime && formData.videoEndTime && formData.videoStartTime >= formData.videoEndTime) newErrors.videoEndTime = 'Окончание позже начала';
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const buildDetails = () => {
    if (type === 'event') return { date: formData.date, startTime: formData.startTime, endTime: formData.endTime, room: formData.room, needVideo: formData.needVideo, needSound: formData.needSound, needProjector: formData.needProjector, extraInfo: formData.extraInfo };
    if (type === 'repair') return { room: formData.repairRoom, description: formData.description };
    return { location: formData.location, startTime: formData.videoStartTime, endTime: formData.videoEndTime, usageInfo: formData.usageInfo };
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;
    try {
      await axios.post('/api/requests', { type, responsibleId: responsibleId || null, details: buildDetails() });
      onCreated();
    } catch { alert('Ошибка создания заявки'); }
  };

  return (
    <form className="request-form" onSubmit={handleSubmit}>
      <h2>Новая заявка</h2>
      <div className="form-group">
        <label>Тип</label>
        <select value={type} onChange={e => setType(e.target.value)}>
          <option value="event">Мероприятие</option>
          <option value="repair">Ремонт</option>
          <option value="video">Видеосъёмка</option>
        </select>
      </div>
      <div className="form-group">
        <label>Ответственный</label>
        <select value={responsibleId} onChange={e => setResponsibleId(e.target.value)}>
          <option value="">Все сотрудники</option>
          {employees.map(emp => <option key={emp.id} value={emp.id}>{emp.surname} {emp.name}</option>)}
        </select>
      </div>
      {type === 'event' && (
        <>
          <div className="form-group"><label>Дата</label><input type="date" name="date" value={formData.date} onChange={handleChange} />{errors.date && <span className="field-error">{errors.date}</span>}</div>
          <div className="form-row"><div className="form-group"><label>Начало</label><input type="time" name="startTime" onChange={handleChange} />{errors.startTime && <span className="field-error">{errors.startTime}</span>}</div>
          <div className="form-group"><label>Окончание</label><input type="time" name="endTime" onChange={handleChange} />{errors.endTime && <span className="field-error">{errors.endTime}</span>}</div></div>
          <div className="form-group"><label>Аудитория</label><select name="room" value={formData.room} onChange={handleChange}><option value="">Выберите</option>{rooms.map(r => <option key={r.id} value={r.number}>{r.number}</option>)}</select>{errors.room && <span className="field-error">{errors.room}</span>}</div>
          <div className="checkbox-group"><label><input type="checkbox" name="needVideo" checked={formData.needVideo} onChange={handleChange} />Видеосъёмка</label><label><input type="checkbox" name="needSound" checked={formData.needSound} onChange={handleChange} />Звукооператор</label><label><input type="checkbox" name="needProjector" checked={formData.needProjector} onChange={handleChange} />Проектор</label></div>
          <div className="form-group"><label>Доп. инфо</label><textarea name="extraInfo" rows="3" onChange={handleChange} /></div>
        </>
      )}
      {type === 'repair' && (
        <>
          <div className="form-group"><label>Аудитория</label><select name="repairRoom" value={formData.repairRoom} onChange={handleChange}><option value="">Выберите</option>{rooms.map(r => <option key={r.id} value={r.number}>{r.number}</option>)}</select>{errors.repairRoom && <span className="field-error">{errors.repairRoom}</span>}</div>
          <div className="form-group"><label>Описание</label><textarea name="description" rows="4" onChange={handleChange} />{errors.description && <span className="field-error">{errors.description}</span>}</div>
        </>
      )}
      {type === 'video' && (
        <>
          <div className="form-group"><label>Место</label><input type="text" name="location" onChange={handleChange} />{errors.location && <span className="field-error">{errors.location}</span>}</div>
          <div className="form-row"><div className="form-group"><label>Начало</label><input type="time" name="videoStartTime" onChange={handleChange} />{errors.videoStartTime && <span className="field-error">{errors.videoStartTime}</span>}</div>
          <div className="form-group"><label>Окончание</label><input type="time" name="videoEndTime" onChange={handleChange} />{errors.videoEndTime && <span className="field-error">{errors.videoEndTime}</span>}</div></div>
          <div className="form-group"><label>Использование</label><textarea name="usageInfo" rows="3" onChange={handleChange} /></div>
        </>
      )}
      <div className="form-actions"><button type="submit">Отправить</button><button type="button" onClick={onCreated}>Отмена</button></div>
    </form>
  );
};

export default RequestForm;
